using System;
using System.Collections;
using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifiedLightningAction", menuName = "Data/Battle/Battle Actions/Purification Actions/Purified Lightning Action")]
public class PurifiedLightningAction : LightningAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	[SerializeField]
	private bool sequenceVFX;

	public PurifyAction PurifyAction => purifyAction;

	public bool EnableVFXDelay => enableVFXDelay;

	public override void CastTargetAmount(GameObject target, int timesAmount, GameObject source)
	{
		SingleTargetCastDefault(target, timesAmount, base.CorruptPurifyAmountWithModifier, source);
	}

	public void SingleTargetCastDefault(GameObject target, int timesAmount, int purifyAmount, GameObject source, Action onEachPurifyAction = null, Action startAction = null, Action afterAllLightningsAction = null)
	{
		ActivateSafeCriticalOmen(source);
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueAction(SingleTargetCast(target, timesAmount, purifyAmount, source, onEachPurifyAction, startAction, afterAllLightningsAction));
		instance.SetState(instance.ActionsQueueState);
	}

	public void SingleTargetCastDefaultBeforeMainActionCoroutine(GameObject target, int timesAmount, int purifyAmount, GameObject source, Action onEachPurifyAction, Action startAction)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueBeforeMainActionAction(SingleTargetCast(target, timesAmount, purifyAmount, source, onEachPurifyAction, startAction));
		instance.SetState(instance.ActionsQueueState);
	}

	private IEnumerator SingleTargetCast(GameObject target, int timesAmount, int purifyAmount, GameObject source, Action onEachPurifyAction = null, Action startAction = null, Action afterAllLightningsAction = null)
	{
		if (startAction != null)
		{
			startAction();
			yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
		}
		else
		{
			yield return InvokeAlternatives.WaitOneFrame();
		}
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		if (sequenceVFX)
		{
			if (IsVFXEnabled())
			{
				ReferenceSingleton<CoroutineHandler>.Instance.Run(VFXCoroutine(timesAmount, target));
				yield return new WaitForSeconds(vfxDelay);
			}
			for (int i = 0; i < timesAmount; i++)
			{
				purifyAction.CastTargetAmountXTime(target, purifyAmount, source);
				onEachPurifyAction?.Invoke();
				yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
			}
		}
		else
		{
			for (int i = 0; i < timesAmount; i++)
			{
				SpawnVFX(GetVFXOwnerPosition(target), 3f);
				if (IsVFXEnabled())
				{
					PlaySFX();
				}
				bool usedVFXDelay = enableVFXDelay && IsVFXEnabled();
				if (usedVFXDelay)
				{
					yield return new WaitForSeconds(vfxDelay);
				}
				purifyAction.CastTargetAmountXTime(target, purifyAmount, source);
				onEachPurifyAction?.Invoke();
				if (!usedVFXDelay)
				{
					yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
				}
			}
		}
		afterAllLightningsAction?.Invoke();
		DeactivateSafeCriticalOmen();
	}

	private IEnumerator VFXCoroutine(int timesAmount, GameObject target)
	{
		for (int i = 0; i < timesAmount; i++)
		{
			PlaySFX();
			SpawnVFX(GetVFXOwnerPosition(target), 4f);
			yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
		}
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int timesAmount, GameObject source)
	{
		ActivateSafeCriticalOmen(source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(MultipleTargetCast(targets, timesAmount, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator MultipleTargetCast(List<GameObject> targets, int timesAmount, GameObject source)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		for (int i = 0; i < timesAmount; i++)
		{
			for (int j = 0; j < targets.Count; j++)
			{
				SpawnVFX(GetVFXOwnerPosition(targets[j]), 3f);
			}
			if (IsVFXEnabled())
			{
				PlaySFX();
			}
			purifyAction.AreaCastTargetAmountXTime(targets, base.CorruptPurifyAmountWithModifier, source);
			yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
		}
		DeactivateSafeCriticalOmen();
	}
}
